/* ===================== 🔥 JOIN GROUP (VIA CODE) ===================== */
/* ===================== 🔥 JOIN GROUP ===================== */
export const joinGroup = async (req, res) => {
  try {
    // 1. Accept either joinCode (manual entry) or groupId (accepting an invite)
    const { joinCode, groupId } = req.body;

    if (!joinCode && !groupId) {
      return res.status(400).json({ message: "Join Code or Group ID is required" });
    }

    let group;
    // 2. Find group by the secure CODE or by the ID
    if (joinCode) {
      group = await Group.findOne({ joinCode });
    } else if (groupId) {
      group = await Group.findById(groupId);
    }

    if (!group) {
      return res.status(404).json({ message: "Group not found or Invalid Invite Code" });
    }

    if (group.members.includes(req.user._id)) {
      return res.status(400).json({ message: "You are already in this group" });
    }

    // 3. Add user to group
    group.members.push(req.user._id);
    await group.save();

    // 4. Remove the group from the user's invitations array so it doesn't stay pending
    const user = await User.findById(req.user._id);
    if (user && user.invitations.includes(group._id)) {
      // Filter out the accepted group ID
      user.invitations = user.invitations.filter(invId => !invId.equals(group._id));
      await user.save();
    }

    res.json({
      message: "Joined successfully!",
      group: { id: group._id, name: group.name }
    });

  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};